const cfg = {threshold:50,w:{demo_or_webinar_registration:40,attended_session:30,fee_or_brochure_page_view:20,program_page_view:10,whatsapp_or_form_enquiry:45,replied_to_email:50,hiring_signal_aep_role:25,icp_title_match:15,personal_email_domain:-20},maxPerDay:25};
const byLead = {};
for (const it of $input.all()) {
  const r = it.json; const k = (r.email||'').toLowerCase().trim(); if (!k) continue;
  if (['yes','true','1'].includes(String(r.unsubscribed||r.do_not_contact||'').toLowerCase())) continue;
  const l = byLead[k] ||= {email:k,name:r.name||'',company:r.company||'',title:r.title||'',signals:new Set(),score:0,touches:Number(r.touches||0),consent:r.consent||''};
  const s = r.signal; if (s && cfg.w[s] !== undefined && !l.signals.has(s)) { l.signals.add(s); l.score += cfg.w[s]; }
}
const out = Object.values(byLead).filter(l => l.score >= cfg.threshold && l.touches < 3).sort((a,b)=>b.score-a.score).slice(0,cfg.maxPerDay);
return out.map(l => ({json:{...l, signals:[...l.signals].join(', ')}}));
